function longestBlock(text) {
  let longest = { length: 0, kind: '-', line: 0 }
  for (const block of renderedBlocks(text)) {
    if (block.text.length > longest.length) {
      longest = { length: block.text.length, kind: block.kind, line: block.line }
    }
  }
  return longest
}

