const alpha = WorkspaceId('workspace:alpha')
const requestId = (v: string): AgentTeamRequestId => v as AgentTeamRequestId

describe('claim 1: follow request id reuse after an unfollow', () => {
  it('replays the stale idempotent result', async () => {
    const pool = new MemoryMediaPool()
    const ctx = new Context()
    await ctx.plugin(Storage)
    ctx.storage.backend.register('memory', new MemoryStorageBackend(pool))
    const facility = new DomainFacility(ctx, { backend: 'memory', routes: {} })
    ctx.storage.mount('domain', facility)
    ctx.provide('storageDomain', facility)
    ctx.provide('workspaceRegistry', { get: (id: WorkspaceId) => ({ id, path: process.cwd(), attachSession: async () => {}, archiveSession: async () => {} }), list: () => [] })
    ctx.provide('agents', { create: async () => { throw new Error('unused') }, resume: async () => { throw new Error('unused') } })
    ctx.provide('agentDefaultModel', { currentSelection: () => ({ provider: 'mock', model: 'mock' }) })
    ctx.provide('agentPresets', { mount: async () => { throw new Error('unused') } })
    ctx.provide('tools', { schemas: () => [] })
    ctx.provide('sessionPersistence', { list: async () => [] })
    provideQuietTokenMeter(ctx)
    await ctx.plugin(SessionProjectionRegistry)
    await ctx.plugin(AgentTeam)
    const project = await ctx.agentTeam.createProject({ requestId: requestId('project'), workspaceId: alpha, name: 'engineering', description: 'Engineering work' })
    const started = await ctx.agentTeam.startThread({ kind: 'task', requestId: requestId('start'), workspaceId: alpha, projectRef: project.project.projectRef, body: 'Task' })
    const taskRef = (started as unknown as { task: { taskRef: string } }).task.taskRef

    // startThread leaves the Human following, so step back to reach a clean start.
    await ctx.agentTeam.changeAttention({ requestId: requestId('u0'), workspaceId: alpha, taskRef, action: 'unfollow' })

    // First follow, with the id the hook would cache under 'follow'.
    const follow = await ctx.agentTeam.changeAttention({ requestId: requestId('same-id'), workspaceId: alpha, taskRef, action: 'follow' })
    // Unfollow through a different id, the way a successful unfollow writes.
    await ctx.agentTeam.changeAttention({ requestId: requestId('other-id'), workspaceId: alpha, taskRef, action: 'unfollow' })
    // Second follow reusing the cached id — exactly what the hook does on the next click.
    const second = await ctx.agentTeam.changeAttention({ requestId: requestId('same-id'), workspaceId: alpha, taskRef, action: 'follow' })

    const result = {
      firstAttention: follow.attention !== undefined,
      secondAttention: second.attention !== undefined,
      secondCommitted: (second as unknown as { committed?: boolean }).committed,
      followersAfterSecond: ctx.agentTeam.threadObservations({ workspaceId: alpha, taskRef }).followers,
    }
    console.log('CLAIM1 RESULT', JSON.stringify(result))
    expect(result.secondAttention).toBe(true)
  })
})

